public class Main {
    static void run(int[] data, int index, int divisor) {
        try {
            System.out.println(data[index] / divisor);
        } catch (ArrayIndexOutOfBoundsException | ArithmeticException e) {
            System.out.println("Caught " + e.getClass().getSimpleName());
        }
    }

    public static void main(String[] args) {
        int[] data = {10, 20, 30};
        run(data, 1, 2);
        run(data, 5, 2);
        run(data, 0, 0);
    }
}
